'use strict';

// MODULES //

var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );


// VARIABLES //

/**
* Truncation functions.
*
* @private
* @name TRUNCATIONS
* @constant
* @type {Object}
*
* @example
* var f = TRUNCATIONS[ 'l2' ];
* // returns <Function>
*/
var TRUNCATIONS = {
	'elasticnet': l1Truncation,
	'l1': l1Truncation,
	'l2': noTruncation,
	'none': noTruncation
};


// FUNCTIONS //

/**
* Applies no truncation.
*
* Note:
*
* -   Here **params**: `[ ]` (empty)
*
* @private
* @param {NonNegativeInteger} N - number of features (length of `w`)
* @param {number} u - cumulative L1 penalty accumulated so far
* @param {NonNegativeInteger} eta - learning rate.
* @param {number} scaleFactor - current scaling factor applied to the stored weights
* @param {Float64Array} w - weight array
* @param {integer} strideW - stride length for `w`
* @param {NonNegativeInteger} offsetW - starting index for `w`
* @param {Float64Array} workspace - workspace array tracking the total L1 shrinkage applied to each feature
* @param {integer} strideWS - stride length for `workspace`
* @param {NonNegativeInteger} offsetWS - starting index for `workspace`
* @param {Float64Array} params - strided array containing regularizer specific parameters.
* @returns {number} u
*/
function noTruncation( N, u, eta, scaleFactor, w, strideW, offsetW, workspace, strideWS, offsetWS, params ) { // eslint-disable-line no-unused-vars, max-len, max-params
	return u;
}

/**
* Applies the cumulative L1 penalty to the weight vector.
*
* Note:
*
* -   Here **params**: `[ lambda, l1Ratio ]`
*
* @private
* @param {NonNegativeInteger} N - number of features
* @param {number} u - cumulative L1 penalty accumulated so far
* @param {NonNegativeInteger} eta - learning rate.
* @param {number} scaleFactor - current scaling factor applied to the stored weights
* @param {Float64Array} w - weight array
* @param {integer} strideW - stride length for `w`
* @param {NonNegativeInteger} offsetW - starting index for `w`
* @param {Float64Array} workspace - workspace array tracking the total L1 shrinkage applied to each feature
* @param {integer} strideWS - stride length for `workspace`
* @param {NonNegativeInteger} offsetWS - starting index for `workspace`
* @param {Float64Array} params - strided array containing regularizer specific parameters.
* @returns {number} u
*/
function l1Truncation( N, u, eta, scaleFactor, w, strideW, offsetW, workspace, strideWS, offsetWS, params ) { // eslint-disable-line max-len, max-params
	var wsIdx;
	var idx;
	var z;
	var j;

	u += ( eta * params[ 0 ] * params[ 1 ] );
	for ( j = 0; j < N; j++ ) {
		idx = offsetW + ( j * strideW );
		wsIdx = offsetWS + ( j * strideWS );
		z = w[ idx ];
		if ( scaleFactor * z > 0.0 ) {
			w[ idx ] = max( 0.0, z - ( ( u + workspace[ wsIdx ] ) / scaleFactor ) ); // eslint-disable-line max-len
		} else if ( scaleFactor * z < 0.0 ) {
			w[ idx ] = min( 0.0, z + ( ( u - workspace[ wsIdx ] ) / scaleFactor ) ); // eslint-disable-line max-len
		}
		workspace[ wsIdx ] += scaleFactor * ( w[ idx ] - z );
	}
	return u;
}


// EXPORTS //

module.exports = TRUNCATIONS;
